  if (connectFn != null) {
    return connectFn(provider: provider, onStatus: io.writeln);
  }
  return runAiinConnectCliFlow(
    onStatus: io.writeln,
    shouldOpenBrowserFn: () => shouldLaunchBrowser(noBrowserFlag: noBrowser),
